
(function(root){const D=root.NeonChargeWalk149Data,previous=root.PolishedSprites.draw;let frames;const ready=new Promise(resolve=>{const im=new Image();im.onload=()=>{frames=D.frames.map(f=>{const[x,y,w,h]=f.rect,c=document.createElement('canvas');c.width=w;c.height=h;const p=c.getContext('2d',{willReadFrequently:true});p.drawImage(im,x,y,w,h,0,0,w,h);const d=p.getImageData(0,0,w,h),v=d.data,mask=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;const seed=(f.seed[1]-y)*w+f.seed[0]-x;queue[tail++]=seed;mask[seed]=1;while(head<tail){const i=queue[head++],xx=i%w;for(const j of[xx?i-1:-1,xx<w-1?i+1:-1,i>=w?i-w:-1,i+w<w*h?i+w:-1])if(j>=0&&!mask[j]&&v[j*4+3]>60){mask[j]=1;queue[tail++]=j;}}for(let i=0;i<mask.length;i++)if(!mask[i])v[i*4+3]=0;p.putImageData(d,0,0);return{image:c,x:x-f.anchor[0],y:y-f.anchor[1],w,h};});resolve(true);};im.onerror=()=>resolve(false);im.src=D.src;});root.PolishedSprites.ready=Promise.all([root.PolishedSprites.ready,ready]);root.PolishedSprites.draw=function(c,f,t,scale){if(f.type==='reina'&&f.act?.name==='chargeHold130'&&f.walk&&frames){const i=Math.floor((((f.walkPhase||0)%1)+1)%1*8)%8,p=frames[i],k=D.scale;c.save();if(f.charge130?.cue&&t<f.charge130.alertUntil){c.shadowColor='#65c8ff';c.shadowBlur=7;}c.drawImage(p.image,p.x*k,p.y*k,p.w*k,p.h*k);c.restore();return true;}return previous(c,f,t,scale);};root.NeonChargeWalk149={ready,frames:()=>frames};})(window);
